based on the colours you see in the following, can you make me several other color schemes that have colours that relate to each other the same?

QMainWindow {
    background-color: #1a1a1a;
}
QWidget {
    color: #f0f0f0;
    background-color: #1a1a1a;
}
QPushButton {
    background-color: #3b82f6;
    color: white;
    border: none;
    padding: 8px 16px;
    border-radius: 4px;
    font-size: 14px;
}
QPushButton:hover {
    background-color: #2563eb;
}
QPushButton:pressed {
    background-color: #1d4ed8;
}
QLineEdit, QTextEdit, QSpinBox, QComboBox {
    background-color: #2a2a2a;
    color: #f0f0f0;
    border: 1px solid #444;
    padding: 6px;
    border-radius: 3px;
}
QLineEdit:focus, QTextEdit:focus {
    border: 1px solid #3b82f6;
}
QTabWidget::pane {
    border: 1px solid #444;
    background-color: #1a1a1a;
}
QTabBar::tab {
    background-color: #2a2a2a;
    color: #f0f0f0;
    padding: 8px 16px;
    border: 1px solid #444;
    border-bottom: none;
}
QTabBar::tab:selected {
    background-color: #3b82f6;
}
QGroupBox {
    border: 1px solid #444;
    margin-top: 10px;
    padding-top: 10px;
}
QGroupBox::title {
    color: #3b82f6;
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 5px;
}

